<?php
namespace App\Models; use App\Models\Concerns\InvalidatesProducts; use Illuminate\Database\Eloquent\{Builder,Model}; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Relations\{BelongsTo,BelongsToMany,HasMany};
class Product extends Model {use HasFactory,InvalidatesProducts; protected $fillable=['product_category_id','title','slug','eyebrow','short_description','overview','problem_statement','value_proposition','icon','featured_image_path','featured_image_alt','hero_style','template','status','is_featured','display_order','published_at','scheduled_for','archived_at','primary_cta_label','primary_cta_url','secondary_cta_label','secondary_cta_url','demo_cta_label','demo_cta_url','documentation_url','meta_title','meta_description','canonical_url','og_title','og_description','og_image_path','robots_index','robots_follow','created_by','updated_by'];protected function casts():array{return ['is_featured'=>'boolean','robots_index'=>'boolean','robots_follow'=>'boolean','published_at'=>'datetime','scheduled_for'=>'datetime','archived_at'=>'datetime'];}public function category():BelongsTo{return $this->belongsTo(ProductCategory::class,'product_category_id');}public function editions():HasMany{return $this->hasMany(ProductEdition::class)->orderBy('display_order');}public function featureGroups():HasMany{return $this->hasMany(ProductFeatureGroup::class)->orderBy('display_order');}public function benefits():HasMany{return $this->hasMany(ProductBenefit::class)->orderBy('display_order');}public function specifications():HasMany{return $this->hasMany(ProductSpecification::class)->orderBy('display_order');}public function galleryItems():HasMany{return $this->hasMany(ProductGalleryItem::class)->orderBy('display_order');}public function useCases():HasMany{return $this->hasMany(ProductUseCase::class)->orderBy('display_order');}public function integrations():HasMany{return $this->hasMany(ProductIntegration::class)->orderBy('display_order');}public function relatedProducts():BelongsToMany{return $this->belongsToMany(self::class,'product_relations','product_id','related_product_id')->withPivot('display_order')->orderByPivot('display_order');}public function relatedSolutions():BelongsToMany{return $this->belongsToMany(Solution::class,'product_solution_relations')->withPivot('display_order')->orderByPivot('display_order');}public function relatedPages():BelongsToMany{return $this->belongsToMany(Page::class,'product_page_relations')->withPivot('display_order')->orderByPivot('display_order');}public function navigationItems():HasMany{return $this->hasMany(NavigationItem::class);}public function homepageItems():HasMany{return $this->hasMany(HomepageItem::class);}public function scopePubliclyVisible(Builder $q):Builder{return $q->whereNull('archived_at')->whereNotNull('short_description')->where(fn(Builder $q)=>$q->where(fn(Builder $x)=>$x->where('status','published')->whereNotNull('published_at')->where('published_at','<=',now()))->orWhere(fn(Builder $x)=>$x->where('status','scheduled')->whereNotNull('scheduled_for')->where('scheduled_for','<=',now())));}public function isPubliclyVisible():bool{return $this->archived_at===null&&trim((string)$this->short_description)!==''&&(($this->status==='published'&&$this->published_at?->lte(now()))||($this->status==='scheduled'&&$this->scheduled_for?->lte(now())));}}